{
  "cvars": {
    "ivs": [
      {
        "description": "Binary indicator for whether there are children in the marriage (primary independent variable). Encoded 1 = yes, 0 = no.",
        "columns": [
          "HasChildren"
        ]
      }
    ],
    "dv": {
      "description": "Count of extramarital affairs in the past year (top-coded in the original survey). Modeled as a count outcome. Column is numeric with original coding preserved.",
      "columns": [
        "Affairs"
      ]
    },
    "controls": [
      {
        "description": "Respondent gender (used both as a control and as a moderator to test whether the effect of children differs by gender). Encoded 1 = male, 0 = female.",
        "is_moderator": true,
        "moderator_on": "Having children",
        "columns": [
          "Male",
          "HasChildren_Male"
        ]
      },
      {
        "description": "Respondent age in years (numeric).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Age"
        ]
      },
      {
        "description": "Number of years married (numeric).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "YearsMarried"
        ]
      },
      {
        "description": "Self-reported religiousness (numeric scale; higher = more religious).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Religiousness"
        ]
      },
      {
        "description": "Education level (numeric code representing highest attained schooling).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Education"
        ]
      },
      {
        "description": "Occupation code (numeric Hollingshead classification).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Occupation"
        ]
      },
      {
        "description": "Self-rated marriage satisfaction (numeric rating 1-5).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Rating"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Required source columns (from schema):\n    # 'affairs','children','gender','age','yearsmarried','religiousness','education','occupation','rating'\n    # Drop rows missing any required raw inputs\n    required_raw = ['affairs', 'children', 'gender', 'age', 'yearsmarried', 'religiousness', 'education', 'occupation', 'rating']\n    df = df.dropna(subset=required_raw)\n\n    # Dependent variable: keep a numeric copy named 'Affairs'\n    df['Affairs'] = pd.to_numeric(df['affairs'], errors='coerce')\n\n    # Independent variable: HasChildren (1=yes, 0=no). Be robust to capitalization/whitespace.\n    df['children'] = df['children'].astype(str)\n    df['HasChildren'] = df['children'].str.strip().str.lower().map(lambda x: 1 if x in ['yes', 'y', 'true', '1'] else 0)\n\n    # Moderator / control: Male indicator from 'gender'\n    df['gender'] = df['gender'].astype(str)\n    df['Male'] = df['gender'].str.strip().str.lower().map(lambda x: 1 if x == 'male' else 0)\n\n    # Numeric controls: coerce to numeric and rename to descriptive final columns\n    df['Age'] = pd.to_numeric(df['age'], errors='coerce')\n    df['YearsMarried'] = pd.to_numeric(df['yearsmarried'], errors='coerce')\n    df['Religiousness'] = pd.to_numeric(df['religiousness'], errors='coerce')\n    df['Education'] = pd.to_numeric(df['education'], errors='coerce')\n    df['Occupation'] = pd.to_numeric(df['occupation'], errors='coerce')\n    df['Rating'] = pd.to_numeric(df['rating'], errors='coerce')\n\n    # Interaction term for moderation test: HasChildren x Male\n    df['HasChildren_Male'] = df['HasChildren'] * df['Male']\n\n    # Drop any rows with NA in the model columns\n    model_cols = ['Affairs', 'HasChildren', 'Male', 'HasChildren_Male', 'Age', 'YearsMarried', 'Religiousness', 'Education', 'Occupation', 'Rating']\n    df = df.dropna(subset=model_cols)\n\n    # Ensure integer types for binary columns\n    df['HasChildren'] = df['HasChildren'].astype(int)\n    df['Male'] = df['Male'].astype(int)\n    df['HasChildren_Male'] = df['HasChildren_Male'].astype(int)\n\n    # Final dataframe contains at least the columns listed in the conceptual model\n    # Return the transformed dataframe\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> any:\n    \"\"\"\n    Fit a count regression to estimate the association between having children and number of affairs.\n    We use a Negative Binomial GLM (log link) to account for overdispersion in the count outcome.\n\n    Model specification:\n      Affairs ~ HasChildren + Male + HasChildren_Male + Age + YearsMarried + Religiousness + Education + Occupation + Rating\n\n    The interaction term tests whether the association of children with affairs differs by gender.\n    \"\"\"\n    df = df.copy()\n\n    # Outcome and design matrix\n    y = df['Affairs']\n    X = df[['HasChildren', 'Male', 'HasChildren_Male', 'Age', 'YearsMarried', 'Religiousness', 'Education', 'Occupation', 'Rating']]\n    X = sm.add_constant(X)\n\n    # Fit Negative Binomial GLM (log link by default)\n    model_nb = sm.GLM(y, X, family=sm.families.NegativeBinomial())\n    results = model_nb.fit()\n\n    # Print and return results (results contains params, pvalues, conf_int, etc.)\n    print(results.summary())\n    return results\n"
}
